describe('Product Search by Keyword', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('[data-testid="search-input"]').should('be.visible');
  });

  it('should display instant search results when user enters a keyword', () => {
    cy.get('[data-testid="search-input"]').type('laptop');

    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);

    cy.get('[data-testid="product-item"]').first().within(() => {
      cy.get('[data-testid="product-name"]').should('contain.text', 'laptop');
    });

    cy.get('[data-testid="search-results-count"]').should('contain.text', 'results');
  });

  it('should update results instantly as user types additional characters', () => {
    cy.get('[data-testid="search-input"]').type('l');
    cy.get('[data-testid="product-item"]').then($items => {
      const initialCount = $items.length;
      expect(initialCount).to.be.greaterThan(0);
    });

    cy.get('[data-testid="search-input"]').type('a');
    cy.get('[data-testid="product-item"]').then($items => {
      const updatedCount = $items.length;
      expect(updatedCount).to.be.greaterThan(0);
    });
  });

  it('should display no results message when search returns empty', () => {
    cy.get('[data-testid="search-input"]').type('xyznonexistentproduct123');

    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain.text', 'No products found');
    cy.get('[data-testid="product-item"]').should('not.exist');
  });

  it('should clear results when search input is cleared', () => {
    cy.get('[data-testid="search-input"]').type('phone');
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);

    cy.get('[data-testid="search-input"]').clear();
    cy.get('[data-testid="search-results"]').should('not.be.visible');
  });

  it('should handle special characters in search keyword', () => {
    cy.get('[data-testid="search-input"]').type('laptop & tablet');

    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="product-item"]').should('have.length.greaterThan', 0);
  });

  it('should be case-insensitive when searching for products', () => {
    cy.get('[data-testid="search-input"]').type('LAPTOP');
    cy.get('[data-testid="product-item"]').then($itemsUppercase => {
      const uppercaseCount = $itemsUppercase.length;
      expect(uppercaseCount).to.be.greaterThan(0);
    });

    cy.get('[data-testid="search-input"]').clear().type('laptop');
    cy.get('[data-testid="product-item"]').then($itemsLowercase => {
      const lowercaseCount = $itemsLowercase.length;
      expect(lowercaseCount).to.be.greaterThan(0);
    });
  });

  it('should display loading state during search', () => {
    cy.get('[data-testid="search-input"]').type('monitor');

    cy.get('[data-testid="search-loading"]').should('be.visible');
    cy.get('[data-testid="search-loading"]').should('not.exist', { timeout: 5000 });
    cy.get('[data-testid="search-results"]').should('be.visible');
  });
});
